  localRole: null,
  game: null, // single BeerGameEngine, solo mode only
  lastSoloConfig: null,
  soloTimerSeconds: 0,
  soloStartingPrice: null,
  activeGlobalNewsId: null,  // solo mode; multiplayer keeps this on state.lobby instead, so it's shared
  localNewsByRole: { retailer: null, wholesaler: null, distributor: null, manufacturer: null }, // one independent slot per role

  // ---- multiplayer ----
  multiplayerRole: null, // 'host' | 'guest'
  transport: null,
  lobby: null, // { code, hostId, numTeams, totalWeeks, holdingCost, stockoutCost, timerSeconds, teams:[{retailer,wholesaler,distributor,manufacturer,facilitator}x5], started }
  serverUrl: null,
  connectionError: null,
  joinError: null,
  connectStatus: null,   // transient 'waking the server' notice while connecting
  joinTempId: null,
  myName: null,
  localTeamIndex: null, // which of the 5 teams (0-4) this browser is seated at, if any
  isAdminHost: false,   // true once the host has actually started hosting (may or may not also occupy a seat)
  teams: null,           // array of lobby.numTeams BeerGameEngine instances, multiplayer mode
  sessionWeek: 1,
  sessionTotalWeeks: 8,
  sessionGameOver: false,
