  facilitatorDone: false,  // single room-wide bool, gates the 4 chain roles' submit UI
  rolesSubmittedThisWeek: { retailer: false, wholesaler: false, distributor: false, manufacturer: false }, // mirrored on every client via the progress broadcast, drives the sequential gate
  incomingOrders: null, // { retailer, wholesaler, distributor, manufacturer } -> the order each role is facing THIS week, or null until its buyer has submitted. Computed by the host and mirrored to every client alongside the progress broadcast.
  submittedOrders: null, // { role -> { typed, placed, ai } } for orders already placed this week; computed by the host, drawn only on the Facilitator's screen
  ivDraft: { ivCapRole: 'retailer', ivCapMax: '12', ivCapRounds: '3', ivCostRole: 'retailer', ivCostHolding: '', ivCostStockout: '' }, // what the Facilitator has typed into the interventions panel, kept across re-draws
  ivError: null,
  liveDrafts: {},           // key "teamIndex:role" -> in-progress (unsubmitted) draft value, Facilitator-visible only
  liveCursors: {},          // key "teamIndex:role" -> {xPct, yPct}, Facilitator-visible only, play screen only
  lastClicks: {},           // key "teamIndex:role" -> {label, ts}, most recent click, Facilitator-visible only
  facilitatorFollowing: null, // which role (if any) the Facilitator has clicked to follow closely
  moveModeFrom: null,       // host "move a player" interaction: {teamIndex, role} currently selected, or null

  // ---- shared play state ----
  draftOrder: '',
  draftDemand: '',
  waitingForOthers: false,
  timer: { remaining: null, duration: 0, id: null },
