// ---------- MULTIPLAYER: HOST LOGIC ----------
function emptyTeam() { return { retailer: null, wholesaler: null, distributor: null, manufacturer: null }; }

function hostRoom(playerName, serverUrl, cfg) {
  const code = generateRoomCode();
  const numTeams = clampInt(cfg.numTeams, MIN_NUM_TEAMS, MAX_NUM_TEAMS, DEFAULT_NUM_TEAMS);
  state.mode = 'multiplayer';
  state.multiplayerRole = 'host';
  state.serverUrl = serverUrl;
  state.isAdminHost = true;
  state.localTeamIndex = null;
  state.localRole = null;
  state.lastNewsAutoWeek = null;
  state.lobbyChimePlayed = false;
  state.lobby = {
    code, hostId: 'H0', numTeams,
    totalWeeks: cfg.totalWeeks, holdingCost: cfg.holdingCost, stockoutCost: cfg.stockoutCost, timerSeconds: cfg.timerSeconds,
    startingPrice: cfg.startingPrice, // host-configurable Facilitator baseline reference (see market.js)
    scenarioConfig: cfg.scenarioConfig, // drives the Facilitator's weekly suggested-demand feature
    activeGlobalNewsId: null, localNewsByRole: { retailer: null, wholesaler: null, distributor: null, manufacturer: null },
    teams: Array.from({ length: numTeams }, emptyTeam),
    facilitatorSeat: null, // single, room-wide seat: one Facilitator oversees every team
    started: false,
  };
  state.transport = new RoomTransport(code, serverUrl);
  state.transport.onError((msg) => { state.connectionError = msg; state.connectStatus = null; render(); });
  state.transport.onStatus((msg) => { state.connectStatus = msg; render(); });
  state.pendingHostDecisions = {};
  state.facilitatorDone = false;
  state.rolesSubmittedThisWeek = { retailer: false, wholesaler: false, distributor: false, manufacturer: false };

  state.transport.onMessage((msg) => {
    if (msg.type === 'request_lobby') {
      state.transport.send({ type: 'lobby_update', lobby: state.lobby });
    } else if (msg.type === 'claim_seat') {
      if (state.lobby.started) return;
      if (msg.role === 'facilitator') {
        if (state.lobby.facilitatorSeat) { state.transport.send({ type: 'claim_rejected', tempId: msg.tempId, reason: 'The Facilitator seat is already taken.' }); return; }
        state.lobby.facilitatorSeat = { id: msg.tempId, name: msg.name, tempId: msg.tempId };
      } else {
        const team = state.lobby.teams[msg.teamIndex];
        if (!team || team[msg.role]) { state.transport.send({ type: 'claim_rejected', tempId: msg.tempId, reason: 'That seat is already taken.' }); return; }
        team[msg.role] = { id: msg.tempId, name: msg.name, tempId: msg.tempId };
      }
      state.transport.send({ type: 'lobby_update', lobby: state.lobby });
      if (state.screen === 'mpLobby') render();
    } else if (msg.type === 'release_seat') {
      if (state.lobby.facilitatorSeat && state.lobby.facilitatorSeat.id === msg.tempId) state.lobby.facilitatorSeat = null;
      state.lobby.teams.forEach(team => {
        CHAIN.forEach(r => { if (team[r] && team[r].id === msg.tempId) team[r] = null; });
      });
      state.transport.send({ type: 'lobby_update', lobby: state.lobby });
      if (state.screen === 'mpLobby') render();
    } else if (msg.type === 'mod_move' || msg.type === 'mod_kick') {
      // Only the room's current Facilitator (verified by tempId, not just
      // self-reported role) is allowed to request these when they're not
      // the host themselves - the host already has direct local access and
      // never needs to send this message.
      const requesterIsFacilitator = state.lobby.facilitatorSeat && state.lobby.facilitatorSeat.tempId === msg.tempId;
      if (!requesterIsFacilitator) return;
      if (msg.type === 'mod_move') {
        if (state.lobby.teams[msg.toTeamIndex][msg.toRole]) return;
        const occupant = state.lobby.teams[msg.fromTeamIndex][msg.fromRole];
        if (!occupant) return;
        state.lobby.teams[msg.fromTeamIndex][msg.fromRole] = null;
        state.lobby.teams[msg.toTeamIndex][msg.toRole] = occupant;
      } else {
        if (msg.role === 'facilitator') {
          state.lobby.facilitatorSeat = null;
        } else {
          if (!state.lobby.teams[msg.teamIndex][msg.role]) return;
          state.lobby.teams[msg.teamIndex][msg.role] = null;
        }
      }
      state.transport.send({ type: 'lobby_update', lobby: state.lobby });
      if (state.screen === 'mpLobby') render();
    } else if (msg.type === 'intervention_request') {
      const fromFacilitator = state.lobby.facilitatorSeat && state.lobby.facilitatorSeat.tempId === msg.tempId;
      if (!fromFacilitator || !state.teams) return;
      applyInterventionsAsHost(msg.interventions);
      if (state.screen === 'play') render();
    } else if (msg.type === 'news_request') {
      const requesterIsFacilitator = state.lobby.facilitatorSeat && state.lobby.facilitatorSeat.tempId === msg.tempId;
      if (!requesterIsFacilitator) return;
      applyNewsChangeAsHost(msg.newsType, msg.newsId, msg.role);
      if (state.screen === 'play') render();
    } else if (msg.type === 'submit_decision') {
      if (!state.teams || state.sessionGameOver) return;
      if (msg.role === 'facilitator') {
        state.pendingHostDecisions.facilitator = msg.value;
        state.facilitatorDone = true;
        state.transport.send({ type: 'facilitator_status', done: true });
        delete state.liveDrafts.facilitator;
      } else {
        state.pendingHostDecisions[msg.teamIndex + ':' + msg.role] = msg.value;
        delete state.liveDrafts[msg.teamIndex + ':' + msg.role];
      }
      broadcastProgress();
      maybeResolveSessionWeek();
      if (state.screen === 'play') render();
    // NOTE: these three used to re-send the message they had just received.
    // That created a runaway loop: the relay broadcasts every message to
    // ALL clients in the room including the sender, so the host received
    // its own re-send, re-sent it again, and so on. A single guest
    // keystroke could generate hundreds of messages a second, which is
    // what made the Facilitator's screen unresponsive. The relay has
    // already delivered these to everyone, so the host only needs to
    // record them locally.
    } else if (msg.type === 'draft_update') {
      state.liveDrafts[msg.teamIndex + ':' + msg.role] = msg.value;
      if (isCurrentlyFollowed(msg.teamIndex, msg.role)) render();
    } else if (msg.type === 'cursor_update') {
      state.liveCursors[msg.teamIndex + ':' + msg.role] = { xPct: msg.xPct, yPct: msg.yPct };
      if (isCurrentlyFollowed(msg.teamIndex, msg.role) && !updateLiveCursorDotOnly(msg.teamIndex, msg.role)) render();
    } else if (msg.type === 'click_event') {
      state.lastClicks[msg.teamIndex + ':' + msg.role] = { label: msg.label, ts: msg.ts };
      if (isCurrentlyFollowed(msg.teamIndex, msg.role)) flashMiniClick(msg.label);
    }
  });

  state.screen = 'mpLobby';
  render();
}

function moveSeat(fromTeamIndex, fromRole, toTeamIndex, toRole) {
  const lobby = state.lobby;
  if (lobby.teams[toTeamIndex][toRole]) return; // target must be empty
  const occupant = lobby.teams[fromTeamIndex][fromRole];
  if (!occupant) return;
  lobby.teams[fromTeamIndex][fromRole] = null;
  lobby.teams[toTeamIndex][toRole] = occupant;
  state.transport.send({ type: 'lobby_update', lobby: state.lobby });
  render();
}

// Host-direct seat removal (used when the acting host/facilitator IS the
// host; guest-facilitator requests go through the mod_kick network message
// instead, since only the host holds the authoritative lobby object).
function kickSeat(teamIndex, role) {
  const lobby = state.lobby;
  if (role === 'facilitator') {
    if (!lobby.facilitatorSeat) return;
    lobby.facilitatorSeat = null;
  } else {
    if (!lobby.teams[teamIndex][role]) return;
    lobby.teams[teamIndex][role] = null;
  }
  state.transport.send({ type: 'lobby_update', lobby: state.lobby });
  render();
}

// Entry points for the right-click moderation menu - route to a direct local
// change if the actor is the host (who already holds the authoritative lobby
// object), or a network request if they're a guest playing Facilitator
// (verified server-side by tempId before the host applies it).
function moderatorMoveSeat(fromTeamIndex, fromRole, toTeamIndex, toRole) {
  if (state.multiplayerRole === 'host') {
    moveSeat(fromTeamIndex, fromRole, toTeamIndex, toRole);
  } else {
    state.transport.send({ type: 'mod_move', tempId: state.joinTempId, fromTeamIndex, fromRole, toTeamIndex, toRole });
  }
}
function moderatorKickSeat(teamIndex, role) {
  if (state.multiplayerRole === 'host') {
    kickSeat(teamIndex, role);
  } else {
    state.transport.send({ type: 'mod_kick', tempId: state.joinTempId, teamIndex, role });
  }
}

let _draftBroadcastTimer = null;
function broadcastDraftThrottled(value) {
  if (!state.transport || state.localTeamIndex == null || !state.localRole) return;
  if (_draftBroadcastTimer) return; // already scheduled, coalesce rapid keystrokes
  _draftBroadcastTimer = setTimeout(() => {
    _draftBroadcastTimer = null;
    state.transport.send({ type: 'draft_update', teamIndex: state.localTeamIndex, role: state.localRole, value });
  }, 300);
}

// Lets the Facilitator see roughly where a role's cursor is and what they
// last clicked while deciding, the same spirit as the existing live-draft
// broadcast above (an extension of the Facilitator's already-elevated
// oversight view, not a new visibility between peers - a chain role's own
// screen never renders anyone else's cursor, only the Facilitator's follow
// panel does). Position is sent as a percentage of the sender's own
// viewport, not raw pixels, since two people's screens are rarely the same
// size - the Facilitator's UI draws it against a fixed-aspect box, so it
// stays meaningful regardless of either side's actual resolution.
let _cursorBroadcastTimer = null;
function broadcastCursorThrottled(xPct, yPct) {
  if (!SHOW_LIVE_CURSOR) return;
  if (!state.transport || state.mode !== 'multiplayer' || state.localTeamIndex == null || !state.localRole) return;
  if (_cursorBroadcastTimer) return;
  _cursorBroadcastTimer = setTimeout(() => {
    _cursorBroadcastTimer = null;
    state.transport.send({ type: 'cursor_update', teamIndex: state.localTeamIndex, role: state.localRole, xPct, yPct });
  }, 120);
}
function broadcastClick(label) {
  if (!state.transport || state.mode !== 'multiplayer' || state.localTeamIndex == null || !state.localRole) return;
  state.transport.send({ type: 'click_event', teamIndex: state.localTeamIndex, role: state.localRole, label, ts: Date.now() });
}
// A short, human-readable label for whatever was clicked, preferring
// visible button/label text over a raw element id, so the Facilitator
// sees "Submit Order" rather than "submitOrderBtn".
function describeClickTarget(el) {
  if (!el) return 'the screen';
  const clickable = el.closest('button, input, select, a, .seat-cell, .scenario-icon-box');
  if (!clickable) return el.tagName ? el.tagName.toLowerCase() : 'the screen';
  const text = (clickable.textContent || '').trim().replace(/\s+/g, ' ').slice(0, 40);
  if (text) return text;
  if (clickable.tagName === 'INPUT') return `the ${clickable.type === 'number' ? 'number' : 'text'} field`;
  return clickable.id || clickable.tagName.toLowerCase();
}
// document-level mousemove/click listeners must NOT be re-attached on every
// render (unlike the button listeners elsewhere in this file, which are
// safe to re-bind since their DOM nodes are freshly created each render -
// document itself persists, so re-binding here would silently stack up
// duplicate listeners and broadcast every movement multiple times over).
let _cursorTrackingBound = false;
function bindCursorTrackingOnce() {
  if (_cursorTrackingBound) return;
  if (state.mode !== 'multiplayer' || !state.localRole || state.localRole === 'facilitator') return;
  _cursorTrackingBound = true;
  if (SHOW_LIVE_CURSOR) document.addEventListener('mousemove', (e) => {
    if (state.screen !== 'play' || !state.localRole || state.localRole === 'facilitator') return;
    const xPct = Math.round((e.clientX / window.innerWidth) * 1000) / 10;
    const yPct = Math.round((e.clientY / window.innerHeight) * 1000) / 10;
    broadcastCursorThrottled(xPct, yPct);
  });
  document.addEventListener('click', (e) => {
    if (state.screen !== 'play' || !state.localRole || state.localRole === 'facilitator') return;
    broadcastClick(describeClickTarget(e.target));
  });
}

function broadcastProgress() {
  let total = 0, submitted = 0;
  const rolesSubmitted = { retailer: false, wholesaler: false, distributor: false, manufacturer: false };
  state.lobby.teams.forEach((team, ti) => {
    CHAIN.forEach(role => {
      if (team[role]) {
        total++;
        if (state.pendingHostDecisions[ti + ':' + role] !== undefined) { submitted++; rolesSubmitted[role] = true; }
      }
    });
  });
  if (state.lobby.facilitatorSeat) {
    total++;
    if (state.pendingHostDecisions.facilitator !== undefined) submitted++;
  }
  // the host applies this to its own local state directly, so its gating
  // logic stays in sync with everyone else without waiting on its own broadcast
  state.rolesSubmittedThisWeek = rolesSubmitted;
  state.incomingOrders = computeIncomingOrdersAsHost();
  state.submittedOrders = computeSubmittedOrdersAsHost();
  state.transport.send({ type: 'progress', submitted, total, rolesSubmitted, incomingOrders: state.incomingOrders, submittedOrders: state.submittedOrders });
  // the order just advanced, so any bot whose turn has now arrived should start
  scheduleBotActivityForWeek();
}

function maybeResolveSessionWeek() {
  let allIn = true;
  state.lobby.teams.forEach((team, ti) => {
    CHAIN.forEach(role => {
      if (team[role] && state.pendingHostDecisions[ti + ':' + role] === undefined) allIn = false;
    });
  });
  if (state.lobby.facilitatorSeat && state.pendingHostDecisions.facilitator === undefined) allIn = false;
  if (allIn) resolveSessionWeek(false);
}

// ---------- AI "PLAYS LIKE A HUMAN" ACTIVITY SIMULATION ----------
// A bot-controlled seat decides its order instantly and invisibly. That's
// fine mechanically, but it means the Facilitator's follow view shows a
// dead screen for AI seats while human seats visibly move and type, which
// makes it look broken and gives the Facilitator nothing to watch.
//
// This makes bot seats emit the same cursor/draft/click activity a human
// would: the cursor drifts toward the order field, the draft value types
// in digit by digit, then it clicks submit. It is purely presentational,
// the actual decision is still made by aiOrderDecision() in the engine and
// is not changed by any of this - if these timers never ran, the exact
// same order would still be placed.
//
// Only the host runs this (it owns the authoritative game state), and it
// only runs in multiplayer, since solo mode has no remote observer.
let _botActivityTimers = [];
// tracks which bot seats have already run their visible routine this week,
// so re-checking the queue as roles submit doesn't restart them mid-motion
let _botActedThisWeek = {};
function clearBotActivity() {
  _botActivityTimers.forEach(t => clearTimeout(t));
  _botActivityTimers = [];
}
// called at the start of each new week, when the whole queue restarts
function resetBotWeek() {
  clearBotActivity();
  _botActedThisWeek = {};
}
// Generates a human-looking cursor path between two points.
//
// The previous version was a single smooth sweep, which still read as
// synthetic. Real pointing movement isn't one gesture: motor-control
// research (and anyone watching their own hand) shows it's a fast
// BALLISTIC launch that deliberately undershoots, followed by one to three
// small CORRECTIVE sub-movements homing in on the target. That
// launch-then-correct rhythm is what actually makes a cursor look
// hand-driven. Modelled here, along with:
//   - asymmetric speed: very fast acceleration, much longer deceleration
//     (a symmetric ease looks mechanical because hands don't brake as
//     gently as they launch)
//   - an arc, since the wrist pivots rather than tracking a straight line
//   - tremor that INCREASES as the cursor slows, matching how fine
//     positioning is shakier than fast travel
//   - occasional mid-flight hesitation on long moves
// Returns [{x, y, dt}] where dt is the delay before that sample.
function humanCursorPath(from, to, opts) {
  opts = opts || {};
  const totalDist = Math.hypot(to.x - from.x, to.y - from.y);
  if (totalDist < 0.5) return [{ x: to.x, y: to.y, dt: 60 }];

  const pts = [];
  let cur = { x: from.x, y: from.y };

  // --- Phase 1: ballistic launch, deliberately stopping short ---
  // Humans cover roughly 85-95% of the distance in the first fast throw.
  const launchFraction = 0.82 + Math.random() * 0.12;
  // where the launch actually lands, including a slight aim error sideways
  const aimError = totalDist * (Math.random() - 0.5) * 0.08;
  const perp = { x: -(to.y - from.y) / totalDist, y: (to.x - from.x) / totalDist };
  const launchTarget = {
    x: from.x + (to.x - from.x) * launchFraction + perp.x * aimError,
    y: from.y + (to.y - from.y) * launchFraction + perp.y * aimError,
  };

  const launchSteps = Math.max(5, Math.min(16, Math.round(totalDist / 4)));
  const arc = (Math.random() < 0.5 ? -1 : 1) * totalDist * (0.05 + Math.random() * 0.09);
  // hesitate mid-flight occasionally on longer moves
  const hesitateAt = totalDist > 30 && Math.random() < 0.35
    ? 0.4 + Math.random() * 0.3 : -1;

  for (let i = 1; i <= launchSteps; i++) {
    const raw = i / launchSteps;
    // Asymmetric ballistic profile: peaks early (fast throw) then decays
    // smoothly, unlike a symmetric ease which reads as mechanical. Using a
    // single continuous curve rather than a piecewise one - an earlier
    // piecewise version reached 92% of the distance by the halfway point,
    // which wasted most of the samples crawling the final few percent and
    // made the tail look stalled.
    const t = 1 - Math.pow(1 - raw, 2.6);
    const tc = Math.max(0, Math.min(1, t));
    const bow = Math.sin(Math.PI * raw) * arc;
    // tremor grows as we slow down: fast travel is smooth, fine approach shakes
    const speedFactor = 1 - Math.abs(0.5 - raw) * 2; // 0 at ends, 1 mid-flight
    const tremor = (Math.random() - 0.5) * (0.25 + (1 - speedFactor) * 0.5);
    cur = {
      x: from.x + (launchTarget.x - from.x) * tc + perp.x * bow + tremor,
      y: from.y + (launchTarget.y - from.y) * tc + perp.y * bow + tremor,
    };
    let dt = 45 + Math.random() * 25;
    if (hesitateAt > 0 && raw >= hesitateAt && raw < hesitateAt + (1 / launchSteps)) {
      dt += 140 + Math.random() * 220; // brief mid-flight pause
    }
    pts.push({ x: cur.x, y: cur.y, dt });
  }

  // --- Phase 2: corrective sub-movements ---
  // One to three progressively smaller homing adjustments, each with its
  // own little reaction delay before it starts. This is the part that most
  // strongly reads as a real hand.
  const corrections = 1 + (Math.random() < 0.55 ? 1 : 0) + (Math.random() < 0.2 ? 1 : 0);
  for (let c = 0; c < corrections; c++) {
    const isLast = c === corrections - 1;
    // reaction delay: the hand notices it's off and adjusts
    const reaction = 70 + Math.random() * 110;
    // each correction closes most of the remaining gap; the last one lands
    const closeTo = isLast ? 1 : 0.6 + Math.random() * 0.25;
    const stepTarget = isLast ? to : {
      x: cur.x + (to.x - cur.x) * closeTo + (Math.random() - 0.5) * 0.8,
      y: cur.y + (to.y - cur.y) * closeTo + (Math.random() - 0.5) * 0.8,
    };
    const gap = Math.hypot(stepTarget.x - cur.x, stepTarget.y - cur.y);
    const subSteps = Math.max(2, Math.min(6, Math.round(gap / 1.6)));
    const startCur = { x: cur.x, y: cur.y };
    for (let i = 1; i <= subSteps; i++) {
      const raw = i / subSteps;
      const t = 1 - Math.pow(1 - raw, 3); // decelerating settle
      const tremor = (Math.random() - 0.5) * 0.22;
      cur = {
        x: startCur.x + (stepTarget.x - startCur.x) * t + (isLast && i === subSteps ? 0 : tremor),
        y: startCur.y + (stepTarget.y - startCur.y) * t + (isLast && i === subSteps ? 0 : tremor),
      };
      pts.push({
        x: cur.x, y: cur.y,
        dt: (i === 1 ? reaction : 0) + 40 + Math.random() * 30,
      });
    }
  }

  // land precisely so the cursor never sits permanently offset
  pts.push({ x: to.x, y: to.y, dt: 45 + Math.random() * 35 });
  return pts;
}

// Small involuntary drift for when the cursor is "resting" - a real hand on
// a mouse is never perfectly still, and a frozen dot is an instant giveaway
// that nobody is actually holding it. Returns samples wandering gently
// around the current point for roughly `durationMs`.
function idleCursorDrift(at, durationMs) {
  const pts = [];
  let elapsed = 0;
  let cx = at.x, cy = at.y;
  while (elapsed < durationMs) {
    const dt = 180 + Math.random() * 320;
    elapsed += dt;
    // wander, but stay tethered near the origin point so it doesn't crawl away
    cx += (Math.random() - 0.5) * 0.9 + (at.x - cx) * 0.25;
    cy += (Math.random() - 0.5) * 0.9 + (at.y - cy) * 0.25;
    pts.push({ x: cx, y: cy, dt });
  }
  return pts;
}

function scheduleBotActivityForWeek() {
  clearBotActivity();
  if (!SHOW_AI_BOT_THEATRE) return;
  if (state.mode !== 'multiplayer' || state.multiplayerRole !== 'host') return;
  if (!state.teams || !state.lobby) return;

  state.teams.forEach((engine, ti) => {
    CHAIN.forEach(role => {
      const isBotSeat = !state.lobby.teams[ti] || !state.lobby.teams[ti][role];
      if (!isBotSeat) return;
      // Only act once this bot's turn has actually come up in the
      // submission order. Without this, a bot would visibly type and click
      // while its own screen still says "waiting for the Facilitator",
      // which looks broken and contradicts the sequential rule everyone
      // else is playing by. Re-checked each time the order advances.
      if (!roleUnlockedFor(role)) return;
      if (_botActedThisWeek[ti + ':' + role]) return;
      _botActedThisWeek[ti + ':' + role] = true;

      // What this bot will actually order, asked of the real engine so the
      // shown value always matches the real decision.
      let target;
      try { target = engine.aiOrderDecision(role); } catch (e) { return; }
      const digits = String(target);

      // Bot seats don't BLOCK the submission order (a bot must never make a
      // real person wait), but their visible activity is still staggered
      // down the chain so a watching Facilitator sees Retailer act, then
      // Wholesaler, then Distributor, then Manufacturer, matching the order
      // everyone is actually playing by. Without this they'd all move at
      // once, which contradicts the rule on screen.
      const orderIdx = Math.max(0, SUBMISSION_ORDER.indexOf(role) - 1);
      let clock = 800 + Math.random() * 1800 + orderIdx * (5200 + Math.random() * 1200);

      // Start wherever this bot's cursor already was, so it continues from
      // its last position across weeks rather than teleporting to a fresh
      // random spot every round.
      const prev = state.liveCursors[ti + ':' + role];
      let cursor = prev ? { x: prev.xPct, y: prev.yPct } : { x: 18 + Math.random() * 25, y: 25 + Math.random() * 25 };

      const emitPath = (to) => {
        if (!SHOW_LIVE_CURSOR) {
          // cursor is off: keep the pacing (so typing/clicks still land at
          // human-looking times) but skip generating and scheduling the
          // dozens of per-sample timers that would all be discarded.
          clock += 700 + Math.random() * 500;
          cursor = to;
          return;
        }
        humanCursorPath(cursor, to).forEach(p => {
          clock += p.dt;
          const px = Math.round(p.x * 10) / 10, py = Math.round(p.y * 10) / 10;
          _botActivityTimers.push(setTimeout(() => {
            emitBotActivity('cursor', ti, role, { xPct: px, yPct: py });
          }, clock));
        });
        cursor = to;
      };
      // Approaching a button and clicking it is its own little motion, not
      // an instant teleport-and-fire. A real hand arrives slightly off,
      // makes a tiny final correction onto the control, holds still for a
      // beat while the finger presses, and the click itself nudges the
      // cursor a hair. Modelled here so clicks don't look mechanical.
      const emitClickOn = (to, label) => {
        if (!SHOW_LIVE_CURSOR) {
          // no cursor to move; just pause as if reaching for the control,
          // then click, so the timing still reads as a person acting
          clock += 800 + Math.random() * 700;
          _botActivityTimers.push(setTimeout(() => {
            emitBotActivity('click', ti, role, { label });
          }, clock));
          cursor = to;
          return;
        }
        // arrive just off-target, the way an aimed move actually lands
        emitPath({ x: to.x + (Math.random() - 0.5) * 3.5, y: to.y + (Math.random() - 0.5) * 2.2 });
        // small final correction onto the control itself
        [0.55, 1].forEach((f, i) => {
          clock += 55 + Math.random() * 45;
          const nx = cursor.x + (to.x - cursor.x) * f;
          const ny = cursor.y + (to.y - cursor.y) * f;
          const px = Math.round(nx * 10) / 10, py = Math.round(ny * 10) / 10;
          _botActivityTimers.push(setTimeout(() => {
            emitBotActivity('cursor', ti, role, { xPct: px, yPct: py });
          }, clock));
          if (i === 1) cursor = { x: to.x, y: to.y };
        });
        // hold still for a beat before the press actually happens
        clock += 130 + Math.random() * 170;
        _botActivityTimers.push(setTimeout(() => {
          emitBotActivity('click', ti, role, { label });
        }, clock));
        // the press itself jostles the cursor very slightly
        clock += 60 + Math.random() * 60;
        const jx = Math.round((cursor.x + (Math.random() - 0.5) * 0.7) * 10) / 10;
        const jy = Math.round((cursor.y + (Math.random() - 0.5) * 0.7) * 10) / 10;
        _botActivityTimers.push(setTimeout(() => {
          emitBotActivity('cursor', ti, role, { xPct: jx, yPct: jy });
        }, clock));
      };

      // A pause where the hand is still ON the mouse: drifts very slightly
      // rather than freezing dead, which is what gives a static dot away.
      const emitPause = (durationMs) => {
        if (!SHOW_LIVE_CURSOR) { clock += durationMs; return; }
        idleCursorDrift(cursor, durationMs).forEach(p => {
          clock += p.dt;
          const px = Math.round(p.x * 10) / 10, py = Math.round(p.y * 10) / 10;
          _botActivityTimers.push(setTimeout(() => {
            emitBotActivity('cursor', ti, role, { xPct: px, yPct: py });
          }, clock));
          cursor = { x: p.x, y: p.y };
        });
      };

      // Wander somewhere in the reading area first (people look before they
      // act), pause as if reading, then head for the input.
      emitPath({ x: 28 + Math.random() * 22, y: 34 + Math.random() * 16 });
      emitPause(500 + Math.random() * 900); // reading

      // move to the order input and click into it
      emitClickOn({ x: 74 + Math.random() * 6, y: 60 + Math.random() * 4 }, 'the number field');

      // types the number in, digit by digit, with uneven keystroke timing.
      // The hand rests on the mouse while typing, so it still drifts a little.
      clock += 200 + Math.random() * 250;
      digits.split('').forEach((_, i) => {
        clock += 130 + Math.random() * 190;
        _botActivityTimers.push(setTimeout(() => {
          emitBotActivity('draft', ti, role, { value: digits.slice(0, i + 1) });
        }, clock));
      });

      // hesitation before committing, then move to submit and click
      emitPause(350 + Math.random() * 700);
      emitClickOn({ x: 72 + Math.random() * 6, y: 84 + Math.random() * 3 }, 'Submit Order');

      // after submitting, the hand doesn't vanish - it keeps resting there
      emitPause(2500 + Math.random() * 3000);
    });
  });
}
// Applies a simulated bot event locally AND relays it, so it reaches the
// Facilitator whether they're the host or a guest - identical delivery
// path to a real human's activity.
function emitBotActivity(kind, teamIndex, role, payload) {
  if (!state.transport) return;
  if (kind === 'cursor' && !SHOW_LIVE_CURSOR) return;
  const key = teamIndex + ':' + role;
  if (kind === 'cursor') {
    state.liveCursors[key] = { xPct: payload.xPct, yPct: payload.yPct };
    state.transport.send({ type: 'cursor_update', teamIndex, role, xPct: payload.xPct, yPct: payload.yPct });
    if (isCurrentlyFollowed(teamIndex, role) && !updateLiveCursorDotOnly(teamIndex, role)) render();
  } else if (kind === 'draft') {
    state.liveDrafts[key] = payload.value;
    state.transport.send({ type: 'draft_update', teamIndex, role, value: payload.value });
    if (isCurrentlyFollowed(teamIndex, role)) render();
  } else if (kind === 'click') {
    state.lastClicks[key] = { label: payload.label, ts: Date.now() };
    state.transport.send({ type: 'click_event', teamIndex, role, label: payload.label, ts: Date.now() });
    if (isCurrentlyFollowed(teamIndex, role)) flashMiniClick(payload.label);
  }
}

// Shows the click actually landing: the targeted control in the mock-up
// depresses briefly and a ripple pulses at the cursor. Done with direct DOM
// classes rather than a re-render, because a click is followed immediately
// by more cursor samples and a full render would fight with them (and drop
// the animation half way through).
function flashMiniClick(label) {
  const dot = document.getElementById('liveCursorDot');
  if (dot) {
    dot.classList.remove('is-clicking');
    void dot.offsetWidth; // force reflow so the animation restarts if clicked twice quickly
    dot.classList.add('is-clicking');
    setTimeout(() => dot.classList.remove('is-clicking'), 420);
  }
  const l = (label || '').toLowerCase();
  let target = null;
  if (l.includes('submit') || l.includes('confirm')) target = document.querySelector('.mini-order-btn');
  else if (l.includes('field') || l.includes('number')) target = document.querySelector('.mini-order-input');
  if (target) {
    target.classList.add('is-pressed');
    setTimeout(() => target.classList.remove('is-pressed'), 260);
  }
}

function resolveSessionWeek(forced) {
  stopTimer();
  // One shared demand value drives every team this week: the single
  // Facilitator's real submission if they're seated and submitted, or one
  // auto-generated number (computed once, not per team) if the seat is
  // empty or they didn't submit in time. Either way, every team faces the
  // same market conditions and is judged on how differently they react to it.
  const sharedDemand = (state.pendingHostDecisions.facilitator !== undefined)
    ? state.pendingHostDecisions.facilitator
    : state.teams[0].autoConsumerDemand(state.teams[0].week);
  const results = state.teams.map((engine, ti) => {
    const decisions = { facilitator: sharedDemand };
    CHAIN.forEach(role => {
      const key = ti + ':' + role;
      if (state.pendingHostDecisions[key] !== undefined) decisions[role] = state.pendingHostDecisions[key];
    });
    return engine.processWeek(decisions);
  });
  state.pendingHostDecisions = {};
  state.facilitatorDone = false;
  state.rolesSubmittedThisWeek = { retailer: false, wholesaler: false, distributor: false, manufacturer: false };
  state.liveDrafts = {};
  state.liveCursors = {};
  state.lastClicks = {};
  state.sessionWeek = state.teams[0].week;
  state.sessionGameOver = state.teams.every(e => e.gameOver);
  maybeAutoPickNews(state.sessionWeek); // before the broadcast below, so it carries any cost change
  state.waitingForOthers = false;
  state.draftOrder = ''; state.draftDemand = ''; state.aiChatStatus = null;
  state.screen = state.sessionGameOver ? 'end' : 'play';
  // fresh week: with a bot-filled Facilitator seat the Retailer's turn is open
  // immediately, so its incoming order is already known at week start
  state.incomingOrders = state.sessionGameOver ? null : computeIncomingOrdersAsHost();
  state.submittedOrders = state.sessionGameOver ? null : computeSubmittedOrdersAsHost();
  state.transport.send({ type: 'week_result', teams: state.teams, gameOver: state.sessionGameOver, incomingOrders: state.incomingOrders, submittedOrders: state.submittedOrders });
  if (!state.sessionGameOver && state.lobby.timerSeconds > 0) startTimer();
  if (state.sessionGameOver) { clearBotActivity(); } else { resetBotWeek(); scheduleBotActivityForWeek(); }
  render();
}

function startHostedGame() {
  const lobby = state.lobby;
  lobby.started = true;
  const facOcc = lobby.facilitatorSeat;
  const facilitatorAssignment = facOcc
    ? { id: facOcc.id, name: facOcc.name, isBot: false }
    : { id: 'BOT', name: 'AI ' + ROLE_LABELS.facilitator, isBot: true };
  state.teams = lobby.teams.map(team => {
    const roleAssignments = { facilitator: facilitatorAssignment };
    CHAIN.forEach(r => {
      const occ = team[r];
      roleAssignments[r] = occ ? { id: occ.id, name: occ.name, isBot: false } : { id: 'BOT', name: 'AI ' + ROLE_LABELS[r], isBot: true };
    });
    return new BeerGameEngine({ roleAssignments, totalWeeks: lobby.totalWeeks, holdingCost: lobby.holdingCost, stockoutCost: lobby.stockoutCost });
  });
  state.sessionWeek = 1;
  state.sessionTotalWeeks = lobby.totalWeeks;
  state.sessionGameOver = false;
  state.rolesSubmittedThisWeek = { retailer: false, wholesaler: false, distributor: false, manufacturer: false };
  state.screen = 'play';
  state.incomingOrders = computeIncomingOrdersAsHost();
  state.submittedOrders = computeSubmittedOrdersAsHost();
  state.transport.send({ type: 'game_started', teams: state.teams, lobby, incomingOrders: state.incomingOrders, submittedOrders: state.submittedOrders });
  if (lobby.timerSeconds > 0) startTimer();
  resetBotWeek();
  scheduleBotActivityForWeek();
  render();
}

// ---------- MULTIPLAYER: JOIN LOGIC ----------
function joinRoom(playerName, roomCode, serverUrl) {
  const code = roomCode.trim().toUpperCase();
  state.joinTempId = 'tmp_' + Math.random().toString(36).slice(2, 10);
  state.mode = 'multiplayer';
  state.multiplayerRole = 'guest';
  state.serverUrl = serverUrl;
  state.joinError = null;
  state.connectionError = null;
  state.localTeamIndex = null;
  state.localRole = null;
  state.lobbyChimePlayed = false;
  state.myName = playerName;
  state.transport = new RoomTransport(code, serverUrl);
  state.transport.onError((msg) => { state.joinError = msg; state.connectStatus = null; state.transport = null; state.screen = 'mpJoin'; render(); });
  state.transport.onStatus((msg) => { state.connectStatus = msg; if (state.screen === 'mpJoin') render(); });

  state.transport.onMessage((msg) => {
    if (msg.type === 'lobby_update') {
      state.lobby = msg.lobby;
      // always re-scan for our own current seat, not just once, so that a
      // host-initiated move (or removal) is correctly reflected on our side too
      let found = null;
      if (state.lobby.facilitatorSeat && state.lobby.facilitatorSeat.tempId === state.joinTempId) {
        found = { ti: null, r: 'facilitator' };
      }
      state.lobby.teams.forEach((team, ti) => {
        CHAIN.forEach(r => { if (team[r] && team[r].tempId === state.joinTempId) found = { ti, r }; });
      });
      state.localTeamIndex = found ? found.ti : null;
      state.localRole = found ? found.r : null;
      if (state.screen === 'mpLobby') render();
    } else if (msg.type === 'claim_rejected') {
      if (msg.tempId !== state.joinTempId) return;
      state.joinError = msg.reason;
      render();
    } else if (msg.type === 'game_started') {
      state.teams = msg.teams.map(deserializeGame);
      state.lobby = msg.lobby;
      // Same reasoning as the news_update handler below: deserializeGame
      // doesn't carry the news-shift fields, so re-derive them from
      // whatever's in msg.lobby right after it's assigned. Typically
      // nothing is active this early, but this keeps every team-rebuild
      // point consistent rather than leaving one silently unprotected.
      applyNewsOrderShiftToAllGames(state.teams);
      state.incomingOrders = msg.incomingOrders || null;
      state.submittedOrders = msg.submittedOrders || null;
      state.sessionWeek = 1;
      state.sessionTotalWeeks = msg.lobby.totalWeeks;
      state.sessionGameOver = false;
      state.facilitatorDone = false;
      state.rolesSubmittedThisWeek = { retailer: false, wholesaler: false, distributor: false, manufacturer: false };
      state.screen = 'play';
      state.draftOrder = ''; state.draftDemand = ''; state.aiChatStatus = null;
      if (msg.lobby.timerSeconds > 0) startTimer();
      render();
    } else if (msg.type === 'progress') {
      const wasUnlocked = state.localRole ? roleUnlockedFor(state.localRole) : true;
      const prevIncoming = state.localRole ? getRevealedIncomingFor(state.localRole) : null;
      if (msg.rolesSubmitted) state.rolesSubmittedThisWeek = msg.rolesSubmitted;
      if (msg.incomingOrders !== undefined) state.incomingOrders = msg.incomingOrders;
      if (msg.submittedOrders !== undefined) state.submittedOrders = msg.submittedOrders;
      // Being newly unlocked is not enough on its own: the Facilitator's "done"
      // message is sent just before this one and can already have opened this
      // role's form, in which case the unlock check below sees nothing new and
      // the incoming order that arrived with this message would never be drawn.
      const incomingChanged = !!state.localRole && state.localRole !== 'facilitator'
        && getRevealedIncomingFor(state.localRole) !== prevIncoming;
      const isUnlockedNow = state.localRole ? roleUnlockedFor(state.localRole) : true;
      updateWaitingBannerOnly(msg.submitted, msg.total);
      // Full re-render only when it actually matters: the local role just
      // got unlocked (reveal their form), or they have no form of their
      // own to disrupt (Facilitator already submitted by this point since
      // they're first in line; a pure-admin host has no seat at all) - an
      // already-unlocked role mid-typing never gets re-rendered just
      // because some unrelated role elsewhere submitted.
      if ((!wasUnlocked && isUnlockedNow) || incomingChanged || state.localRole === 'facilitator' || (state.isAdminHost && !state.localRole)) {
        render();
      }
    } else if (msg.type === 'facilitator_status') {
      state.facilitatorDone = !!msg.done;
      render();
    } else if (msg.type === 'draft_update') {
      state.liveDrafts[msg.teamIndex + ':' + msg.role] = msg.value;
      if (isCurrentlyFollowed(msg.teamIndex, msg.role)) render();
    } else if (msg.type === 'cursor_update') {
      state.liveCursors[msg.teamIndex + ':' + msg.role] = { xPct: msg.xPct, yPct: msg.yPct };
      if (isCurrentlyFollowed(msg.teamIndex, msg.role) && !updateLiveCursorDotOnly(msg.teamIndex, msg.role)) render();
    } else if (msg.type === 'click_event') {
      state.lastClicks[msg.teamIndex + ':' + msg.role] = { label: msg.label, ts: msg.ts };
      if (isCurrentlyFollowed(msg.teamIndex, msg.role)) render();
    } else if (msg.type === 'week_result') {
      state.teams = msg.teams.map(deserializeGame);
      // This fires every single week, and without reapplying here a
      // guest's shift would silently reset to 0 after every resolution,
      // even while news is still genuinely active - by far the most
      // important of the three deserializeGame sites to cover correctly.
      applyNewsOrderShiftToAllGames(state.teams);
      state.incomingOrders = msg.incomingOrders || null;
      state.submittedOrders = msg.submittedOrders || null;
      state.sessionWeek = state.teams[0].week;
      state.sessionGameOver = msg.gameOver;
      state.waitingForOthers = false;
      state.draftOrder = ''; state.draftDemand = ''; state.aiChatStatus = null;
      state.liveDrafts = {};
      state.liveCursors = {};
      state.lastClicks = {};
      state.facilitatorDone = false; // reset for the new week - a guest never gets its own resolveSessionWeek() call to do this locally
      state.rolesSubmittedThisWeek = { retailer: false, wholesaler: false, distributor: false, manufacturer: false };
      state.screen = msg.gameOver ? 'end' : 'play';
      if (!msg.gameOver && state.lobby.timerSeconds > 0) startTimer();
      render();
    } else if (msg.type === 'intervention_update') {
      if (!state.teams) return;
      applyInterventionsToAll(msg.interventions);
      if (msg.incomingOrders !== undefined) state.incomingOrders = msg.incomingOrders;
      if (msg.submittedOrders !== undefined) state.submittedOrders = msg.submittedOrders;
      if (state.screen === 'play') render();
    } else if (msg.type === 'news_update') {
      if (state.lobby) {
        state.lobby.activeGlobalNewsId = msg.activeGlobalNewsId;
        state.lobby.localNewsByRole = msg.localNewsByRole;
      }
      if (msg.teams) state.teams = msg.teams.map(deserializeGame);
      // teams above were just rebuilt fresh from deserialized data, which
      // does not carry activeOrderShift/activeLocalOrderShiftByRole (those
      // aren't part of the serialization schema) - so those fields would
      // otherwise silently reset to 0 on every news update. Re-derive them
      // immediately from the news state that was just synced in, same as
      // the host already does on its own side.
      applyNewsOrderShiftToAllGames(state.teams);
      if (msg.incomingOrders !== undefined) state.incomingOrders = msg.incomingOrders;
      if (msg.submittedOrders !== undefined) state.submittedOrders = msg.submittedOrders;
      if (state.screen === 'play') render();
    }
  });

  state.screen = 'mpLobby';
  render();
  state.transport.send({ type: 'request_lobby' });
}

function claimSeat(teamIndex, role) {
  if (state.multiplayerRole === 'host') {
    if (role === 'facilitator') {
      if (state.lobby.facilitatorSeat) return;
      state.lobby.facilitatorSeat = { id: 'H0_SELF', name: state.playerName || 'Host', tempId: 'H0_SELF' };
      state.localTeamIndex = null;
      state.localRole = 'facilitator';
    } else {
      if (state.lobby.teams[teamIndex][role]) return;
      state.lobby.teams[teamIndex][role] = { id: 'H0_SELF', name: state.playerName || 'Host', tempId: 'H0_SELF' };
      state.localTeamIndex = teamIndex;
      state.localRole = role;
    }
    state.transport.send({ type: 'lobby_update', lobby: state.lobby });
    render();
  } else {
    state.transport.send({ type: 'claim_seat', teamIndex, role, tempId: state.joinTempId, name: state.myName });
  }
}
function releaseSeat() {
  if (!state.localRole) return;
  if (state.multiplayerRole === 'host') {
    if (state.localRole === 'facilitator') { state.lobby.facilitatorSeat = null; }
    else { state.lobby.teams[state.localTeamIndex][state.localRole] = null; }
    state.localTeamIndex = null; state.localRole = null;
    state.transport.send({ type: 'lobby_update', lobby: state.lobby });
    render();
  } else {
    state.transport.send({ type: 'release_seat', tempId: state.joinTempId });
    state.localTeamIndex = null; state.localRole = null;
    render();
  }
}
function leaveRoom() {
  stopTimer();
  clearBotActivity();
  if (state.transport) { if (state.multiplayerRole === 'guest') releaseSeat(); state.transport.close(); }
  Object.assign(state, {
    screen: 'modeSelect', mode: null, localRole: null, localTeamIndex: null, multiplayerRole: null, transport: null,
    lobby: null, teams: null, pendingHostDecisions: {}, facilitatorDone: false, waitingForOthers: false,
    joinError: null, connectionError: null, isAdminHost: false, moveModeFrom: null, facilitatorFollowing: null, liveDrafts: {}, liveCursors: {}, lastClicks: {},
  });
  render();
}
function updateWaitingBannerOnly(submitted, total) {
  const el = document.getElementById('waitingBanner');
  if (el) el.textContent = `Waiting for other roles: ${submitted}/${total} submitted...`;
}
// Is (teamIndex, role) the one role the Facilitator currently has open in
// their Follow panel? Live draft/cursor/click updates from every OTHER
// role arrive constantly while people are deciding, and none of them are
// visible anywhere on screen unless this is true - re-rendering for them
// anyway was the actual cause of the Facilitator's screen lagging under
// real play: with 4 people's mice each broadcasting several times a
// second, that added up to dozens of full-screen re-renders every second,
// the vast majority for roles nobody was even looking at.
function isCurrentlyFollowed(teamIndex, role) {
  if (state.screen !== 'play' || state.localRole !== 'facilitator') return false;
  const f = state.facilitatorFollowing;
  return !!f && f.teamIndex === teamIndex && f.role === role;
}
// Cursor position updates arrive frequently (throttled to ~8/sec) - a full
// render() on every one would be wasteful and could disrupt the
// Facilitator's own typing if they're mid-decision themselves. This only
// moves the dot directly if it's already on screen (i.e. the Facilitator
// is actively following that exact role); otherwise there's nothing to
// update and it's a no-op.
function updateLiveCursorDotOnly(teamIndex, role) {
  const dot = document.getElementById('liveCursorDot');
  if (!dot || dot.dataset.teamIndex != teamIndex || dot.dataset.role !== role) return false;
  const pos = state.liveCursors[teamIndex + ':' + role];
  if (!pos) return false;
  dot.style.left = pos.xPct + '%';
  dot.style.top = pos.yPct + '%';
  return true;
}
function deserializeGame(data) {
  const shell = new BeerGameEngine({ roleAssignments: data.roleAssignments, totalWeeks: data.totalWeeks, holdingCost: data.holdingCost, stockoutCost: data.stockoutCost });
  Object.assign(shell, data);
  return shell;
}

// ---------- MANUAL / TIMER CONTROL ----------
function startTimer() {
  stopTimer();
  const duration = (state.mode === 'solo') ? (state.soloTimerSeconds || 0) : (state.lobby ? state.lobby.timerSeconds : 0);
  if (!duration) return;
  state.timer.duration = duration;
  state.timer.remaining = duration;
  state.timer.id = setInterval(() => {
    state.timer.remaining -= 1;
    if (state.timer.remaining <= 0) {
      stopTimer();
      if (state.mode === 'solo') {
        autoResolveSoloOnTimeout();
      } else if (state.multiplayerRole === 'host') {
        resolveSessionWeek(true); // manual/timer-forced advance
      }
      return;
    }
    updateTimerDisplay();
  }, 1000);
}
// Timer expired in solo play without the human submitting. Resolve the week
// with an AI-assisted decision standing in for the player, exactly the same
// fallback multiplayer uses for an unresponsive human. The seat stays
// human-controlled; it's just AI-played for this one turn.
function autoResolveSoloOnTimeout() {
  if (!state.game || state.game.gameOver) return;
  state.game.processWeek({}); // no decisions supplied; every role, including the human's, falls back to AI for this turn only
  state.draftOrder = ''; state.draftDemand = ''; state.aiChatStatus = null;
  state.screen = state.game.gameOver ? 'end' : 'play';
  if (!state.game.gameOver && state.soloTimerSeconds > 0) startTimer();
  render();
}
function stopTimer() {
  if (state.timer.id) clearInterval(state.timer.id);
  state.timer.id = null;
}
function updateTimerDisplay() {
  const el = document.getElementById('timerDisplay');
  if (el && state.timer.remaining != null) {
    el.textContent = formatMmSs(state.timer.remaining);
    el.classList.toggle('timer-low', state.timer.remaining <= 15);
  }
}

// ---------- LOBBY: role columns × team rows ----------
function renderMpLobby() {
  const lobby = state.lobby;
  if (!lobby) return `<div class="setup-wrap"><div class="setup-card"><div class="hint">Connecting…</div></div></div>`;
  const isHost = state.multiplayerRole === 'host';
  const isModerator = isHost || state.localRole === 'facilitator';
  let filled = 0, capacity = 0;
  lobby.teams.forEach(team => CHAIN.forEach(r => { capacity++; if (team[r]) filled++; }));
  capacity++; if (lobby.facilitatorSeat) filled++;

  const fac = lobby.facilitatorSeat;
  const isMineFac = state.localRole === 'facilitator';
  const facCanClick = isHost ? true : !fac;

  return `
  <div class="setup-wrap lobby-wrap-wide">
    <div class="setup-card lobby-card-wide">
      <div class="brand"><div class="brand-mark">👥</div><h1>Room Lobby</h1></div>
      <div class="room-code-box">
        <span class="hud-label">Room Code</span>
        <span class="room-code-row"><span class="room-code">${lobby.code}</span><button class="btn-copy-code" id="copyRoomCodeBtn" title="Copy room code">📋 Copy</button></span>
        <span class="badge ${state.serverUrl ? 'badge-ok' : 'badge-blue'}" style="margin-top:6px;">${state.serverUrl ? '🌐 Online: any device' : '💻 Same-device only'}</span>
        <span class="hint" style="margin-top:6px;">${filled}/${capacity} seats filled · ${lobby.totalWeeks} weeks · Holding ${fmtDollar(lobby.holdingCost)}/wk · Stockout ${fmtDollar(lobby.stockoutCost)}/wk${lobby.timerSeconds ? ' · ' + formatMmSs(lobby.timerSeconds) + ' timer/week' : ' · manual pacing'}</span>
      </div>
      <div class="field">
        <label>Facilitator <span class="opt-tag">one seat for the room; sets weekly demand</span></label>
        <button class="seat-cell facilitator-seat ${fac ? 'seat-filled' : 'seat-open'} ${isMineFac ? 'seat-mine' : ''}" id="facilitatorSeatBtn" ${!facCanClick ? 'disabled' : ''}>
          ${ROLE_ICON.facilitator} ${fac ? fac.name + (isMineFac ? ' (You)' : '') : 'Open, click to claim'}
        </button>
      </div>
      ${state.moveModeFrom ? `<div class="hint warning-banner warning-banner-amber" style="margin-bottom:8px;">↔ Pick an empty seat to move that player there, or right-click anywhere to cancel.</div>` : ''}
      ${isHost ? `<div class="hint" style="margin-bottom:8px;">As host, click any filled seat then an empty seat to move that player, or right-click a filled seat for more options. Click the Facilitator seat to claim or release it directly. Click Start when ready; empty seats are AI-filled.</div>`
        : isModerator ? `<div class="hint" style="margin-bottom:8px;">As Facilitator, right-click any filled seat to move or remove that player. Click any open seat to claim it for yourself.</div>`
        : `<div class="hint" style="margin-bottom:8px;">Click any open seat below to claim it.</div>`}
      <div class="team-grid-wrap">
        <table class="team-grid">
          <thead><tr>${lobby.teams.length > 1 ? '<th class="team-grid-corner">Team</th>' : ''}${CHAIN.map(r => `<th>${ROLE_ICON[r]} ${ROLE_LABELS[r]}</th>`).join('')}</tr></thead>
          <tbody>
            ${lobby.teams.map((team, ti) => `
              <tr>
                ${lobby.teams.length > 1 ? `<td class="team-grid-label">Team ${ti + 1}</td>` : ''}
                ${CHAIN.map(r => {
                  const occ = team[r];
                  const isMine = state.localTeamIndex === ti && state.localRole === r;
                  const isMoveSource = state.moveModeFrom && state.moveModeFrom.teamIndex === ti && state.moveModeFrom.role === r;
                  const canClick = isHost ? true : !occ;
                  return `<td>
                    <button class="seat-cell ${occ ? 'seat-filled' : 'seat-open'} ${isMine ? 'seat-mine' : ''} ${isMoveSource ? 'seat-move-source' : ''}"
                      data-team="${ti}" data-role="${r}" ${!canClick ? 'disabled' : ''}>
                      ${occ ? occ.name + (isMine ? ' (You)' : '') : 'Open'}
                    </button>
                  </td>`;
                }).join('')}
              </tr>`).join('')}
          </tbody>
        </table>
      </div>
      ${isHost ? `<button class="btn-primary btn-block" id="startHostedBtn">Start Game</button>` : `<div class="hint" style="text-align:center;">Waiting for the host to start…</div>`}
      <button class="btn-secondary btn-block" id="leaveRoomBtn">Leave Room</button>
    </div>
  </div>`;
}
function fallbackCopy(text, onDone) {
  try {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    document.execCommand('copy');
    document.body.removeChild(ta);
    onDone();
  } catch (e) { /* clipboard genuinely unavailable; the code is on screen anyway */ }
}
function bindMpLobbyEvents() {
  const copyBtn = document.getElementById('copyRoomCodeBtn');
  if (copyBtn) copyBtn.addEventListener('click', () => {
    const code = state.lobby ? state.lobby.code : '';
    // navigator.clipboard needs a secure context (https/localhost); this
    // game is often opened straight from a file:// path, so fall back to
    // the old execCommand approach rather than silently doing nothing.
    const done = () => { copyBtn.textContent = '✓ Copied'; setTimeout(() => { copyBtn.textContent = '📋 Copy'; }, 1500); };
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(code).then(done).catch(() => fallbackCopy(code, done));
    } else {
      fallbackCopy(code, done);
    }
  });
  if (!state.lobbyChimePlayed) { state.lobbyChimePlayed = true; playLobbyChime(); }
  const isHost = state.multiplayerRole === 'host';
  const isModerator = isHost || state.localRole === 'facilitator';
  document.querySelectorAll('.seat-cell:not([disabled])').forEach(btn => {
    btn.addEventListener('click', () => {
      if (btn.id === 'facilitatorSeatBtn') {
        const occupied = btn.classList.contains('seat-filled');
        const isMine = state.localRole === 'facilitator';
        if (isHost && occupied && isMine) { releaseSeat(); return; } // host clicking their own seat releases it
        if (isHost && occupied) return; // someone else's seat, host can't move facilitator (only one slot to move to)
        if (!occupied) claimSeat(null, 'facilitator');
        return;
      }
      const teamIndex = Number(btn.dataset.team), role = btn.dataset.role;
      const occupied = btn.classList.contains('seat-filled');
      if (isHost) {
        if (state.moveModeFrom) {
          if (occupied) {
            // clicking another filled seat while a move is pending just re-targets the source
            state.moveModeFrom = { teamIndex, role };
            render();
          } else {
            moveSeat(state.moveModeFrom.teamIndex, state.moveModeFrom.role, teamIndex, role);
            state.moveModeFrom = null;
          }
        } else if (occupied) {
          state.moveModeFrom = { teamIndex, role };
          render();
        } else {
          claimSeat(teamIndex, role); // host claiming an open seat for themself
        }
      } else if (isModerator && state.moveModeFrom) {
        // a guest-Facilitator completing a move they started via the
        // right-click menu; goes through the network request path
        if (occupied) {
          state.moveModeFrom = { teamIndex, role };
          render();
        } else {
          moderatorMoveSeat(state.moveModeFrom.teamIndex, state.moveModeFrom.role, teamIndex, role);
          state.moveModeFrom = null;
          render();
        }
      } else if (!occupied) {
        claimSeat(teamIndex, role);
      }
    });
  });

  // Right-click moderation menu: available to the host and to whoever is
  // currently seated as Facilitator, even if that's not the host. Only
  // shows on seats that are actually occupied - nothing to move or remove
  // from an empty one.
  if (isModerator) {
    document.querySelectorAll('.seat-cell.seat-filled').forEach(btn => {
      btn.addEventListener('contextmenu', (e) => {
        e.preventDefault();
        e.stopPropagation();
        const isFacSeat = btn.id === 'facilitatorSeatBtn';
        const teamIndex = isFacSeat ? null : Number(btn.dataset.team);
        const role = isFacSeat ? 'facilitator' : btn.dataset.role;
        showModContextMenu(e.clientX, e.clientY, teamIndex, role);
      });
    });
  }
  if (state.moveModeFrom) {
    document.addEventListener('contextmenu', cancelMoveMode, { once: true });
  }

  const startBtn = document.getElementById('startHostedBtn');
  if (startBtn) startBtn.addEventListener('click', () => startHostedGame());
  const leaveBtn = document.getElementById('leaveRoomBtn');
  if (leaveBtn) leaveBtn.addEventListener('click', () => leaveRoom());
}

function showModContextMenu(x, y, teamIndex, role) {
  closeModContextMenu();
  const menu = document.createElement('div');
  menu.className = 'mod-context-menu';
  menu.id = 'modContextMenu';
  menu.style.left = x + 'px';
  menu.style.top = y + 'px';
  const canMove = role !== 'facilitator'; // only one Facilitator slot exists, nowhere to move it to
  menu.innerHTML = `
    ${canMove ? '<button type="button" class="mod-context-item" id="modMenuMove">↔ Move to another role</button>' : ''}
    <button type="button" class="mod-context-item mod-context-danger" id="modMenuRemove">✕ Remove from room</button>`;
  document.body.appendChild(menu);
  const moveBtn = document.getElementById('modMenuMove');
  if (moveBtn) moveBtn.addEventListener('click', () => {
    state.moveModeFrom = { teamIndex, role };
    closeModContextMenu();
    render();
  });
  document.getElementById('modMenuRemove').addEventListener('click', () => {
    moderatorKickSeat(teamIndex, role);
    closeModContextMenu();
  });
  setTimeout(() => {
    document.addEventListener('click', closeModContextMenu, { once: true });
    document.addEventListener('contextmenu', closeModContextMenu, { once: true });
  }, 0);
}
function closeModContextMenu() {
  const existing = document.getElementById('modContextMenu');
  if (existing) existing.remove();
}
function cancelMoveMode(e) {
  if (e) e.preventDefault();
  if (state.moveModeFrom) { state.moveModeFrom = null; render(); }
}

// ---------- PLAY SCREEN ----------
function renderPlay() {
  const isMulti = state.mode === 'multiplayer';
  const isPureAdmin = isMulti && state.isAdminHost && state.localTeamIndex == null && state.localRole == null;
  const game = getMyGame();
  const view = isPureAdmin ? null : getMyRoleState();
  const isFacilitator = state.localRole === 'facilitator';
  const week = isMulti ? state.sessionWeek : (game ? game.week : 1);
  const totalWeeks = isMulti ? state.sessionTotalWeeks : (game ? game.totalWeeks : 8);
  const hudSub = isPureAdmin ? 'Host (overseeing the room)'
    : isFacilitator ? 'Facilitator'
    : ROLE_LABELS[state.localRole];

  return `
  <div class="app-shell">
    <div class="hud">
      <div class="hud-left"><div class="hud-title">🍺 The Beer Game</div>
        <div class="hud-sub">${hudSub}${isMulti ? ' · Room ' + state.lobby.code : ''}</div>
      </div>
      <div class="hud-mid">
        <div class="hud-stat"><span class="hud-label">Week</span><span class="hud-val">${week}<small>/${totalWeeks}</small></span></div>
        ${(!isPureAdmin && !isFacilitator) ? `
        <div class="hud-stat"><span class="hud-label">Stock</span><span class="hud-val">${view.own.stock}</span></div>
        <div class="hud-stat"><span class="hud-label">Backlog</span><span class="hud-val ${view.own.backlog>0?'neg':''}">${view.own.backlog}</span></div>
        <div class="hud-stat"><span class="hud-label">Total Cost</span><span class="hud-val">${fmtDollar(view.own.totalCost)}</span></div>` : ''}
        ${((isMulti && state.lobby.timerSeconds > 0) || (state.mode === 'solo' && state.soloTimerSeconds > 0)) ? `<div class="hud-stat"><span class="hud-label">Timer</span><span id="timerDisplay" class="hud-val timer-val">${state.timer.remaining != null ? formatMmSs(state.timer.remaining) : '--'}</span></div>` : ''}
      </div>
      <div class="hud-right">
        ${!isMulti ? `<button class="btn-help" id="restartBtnHud" title="Restart">🔄 Restart</button>` : ''}
      </div>
    </div>
    ${state.waitingForOthers ? `<div class="waiting-banner" id="waitingBanner">Waiting for other roles to submit...</div>` : ''}
    <div class="play-body">
      ${isPureAdmin ? '' : renderRoster(game)}
      <div class="tab-content">
        ${isMulti && state.multiplayerRole === 'host' ? renderHostAdminPanel() : ''}
        ${isPureAdmin ? '' : (isFacilitator ? renderFacilitatorPanel(game, view) : renderRolePanel(game, view))}
      </div>
    </div>
  </div>
  <div id="modalRoot"></div>`;
}

// Host-only overview: who has submitted, across every team. No cost figures
// shown here either, consistent with hidden information; this is purely
// operational (who's ready), not a performance view.
function renderHostAdminPanel() {
  if (!state.teams) return '';
  const facSubmitted = state.pendingHostDecisions.facilitator !== undefined;
  const nextUpRole = SUBMISSION_ORDER.find(r => !roleHasSubmitted(r));
  return `
  <div class="panel" style="margin-bottom:18px;">
    <div class="card">
      <h3>🛠️ Host Controls: Week ${state.sessionWeek}</h3>
      <p class="hint">Submission order this week: Facilitator → Retailer → Wholesaler → Distributor → Manufacturer.</p>
      ${nextUpRole ? `<p class="hint"><b>Currently waiting on:</b> ${ROLE_ICON[nextUpRole]} ${ROLE_LABELS[nextUpRole]}</p>` : `<p class="hint"><b>Everyone has submitted</b> for this week.</p>`}
      <p class="hint">${ROLE_ICON.facilitator} Facilitator: ${state.lobby.facilitatorSeat ? (facSubmitted ? '<span class="badge badge-ok">✓ Submitted</span>' : '<span class="badge badge-blue">… Waiting</span>') : '<span class="hint">AI-driven, no human seated</span>'}</p>
      <table class="mini-table">
        <thead><tr>${CHAIN.map(r => `<th>${ROLE_ICON[r]} ${ROLE_LABELS[r]}</th>`).join('')}</tr></thead>
        <tbody>
          ${state.lobby.teams.map((team, ti) => `<tr>${CHAIN.map(r => {
            const occ = team[r];
            if (!occ) return '<td class="hint">AI</td>';
            const submitted = state.pendingHostDecisions[ti + ':' + r] !== undefined;
            const seen = (submitted && state.localRole === 'facilitator') ? getSubmittedOrderFor(r) : null;
            return `<td>${submitted ? `<span class="badge badge-ok">✓${seen ? ' ' + seen.placed : ''}</span>` : '<span class="badge badge-blue">…</span>'}</td>`;
          }).join('')}</tr>`).join('')}
        </tbody>
      </table>
      ${SHOW_FORCE_ADVANCE ? `<button class="btn-secondary btn-block" id="forceAdvanceBtn" style="margin-top:12px;">⏭️ Force-Advance This Week</button>` : ''}
    </div>
  </div>`;
}

// Roster sidebar: deliberately shows WHO is playing WHAT role on your own
// team, never their numbers. A real cost-ranked leaderboard here would leak
// exactly the information hiding this game depends on to demonstrate the
// bullwhip effect; that ranking only appears once the game is over.
function renderRoster(game) {
  const isMulti = state.mode === 'multiplayer';
  return `
  <div class="roster-sidebar">
    <h4>🏆 ${isMulti ? 'Players in This Room' : 'Players in This Game'}</h4>
    <div class="roster-list">
      ${ROLE_ORDER.map(r => {
        const a = game.roleAssignments[r];
        const isMe = r === state.localRole;
        return `
        <div class="roster-row ${isMe ? 'roster-me' : ''}">
          <span class="roster-icon">${ROLE_ICON[r]}</span>
          <div class="roster-info">
            <div class="roster-role">${ROLE_LABELS[r]}</div>
            <div class="roster-name">${a.name}${a.isBot ? ' <span class="badge-tiny">AI</span>' : ''}${isMe ? ' <span class="badge-tiny you">You</span>' : ''}</div>
          </div>
        </div>`;
      }).join('')}
    </div>
    <p class="hint roster-hint">Costs and stock stay private to each role until the game ends. That's the whole point of the exercise.</p>
  </div>`;
}

// Two text boxes every role sees: Global News always shows the active
// headline (it affects everyone the same way), Local News only shows a
// headline if it specifically targets THIS role - otherwise it just says
// so, since local news is deliberately not everyone's business.
// Formats a news item's mandatory order-shift as a short, unambiguous
// phrase - "+3 units to your order" / "-2 units to your order" / no phrase
// at all when the shift is exactly 0, since "+0" reads as noise rather
// than information. Shared by both the Global and Local news boxes so the
// two stay visually and grammatically consistent.
function formatOrderShift(shift) {
  if (!shift) return '';
  const sign = shift > 0 ? '+' : '';
  return ` (${sign}${shift} unit${Math.abs(shift) === 1 ? '' : 's'} to your order)`;
}

// Shows how Global News and this role's own Local News combine - the
// point being to make the INTERACTION visible, not just each source's
// number in isolation. Two active effects that individually look small
// can combine into something much bigger (or can partially cancel out),
// and a player - or the Facilitator watching all 4 roles at once -
// should be able to see that combined total plainly rather than having
// to add two numbers shown in two different boxes themselves.
function formatCombinedShift(globalShift, localShift) {
  const total = (globalShift || 0) + (localShift || 0);
  if (!globalShift && !localShift) return '';
  const sign = total > 0 ? '+' : '';
  const globalSign = globalShift > 0 ? '+' : '';
  const localSign = localShift > 0 ? '+' : '';
  return `<div class="news-combined-total">Total adjustment this week: <b>${sign}${total}</b> ` +
    `<span class="hint">(Global ${globalSign}${globalShift || 0}, Local ${localSign}${localShift || 0})</span></div>`;
}

function renderNewsBoxes(role) {
  const globalNews = getActiveGlobalNews();
  const globalShift = globalNews ? (globalNews.effect.orderShift || 0) : 0;
  const globalBox = `
    <div class="news-box news-box-global">
      <b>🌍 Global News</b>
      <p>${globalNews ? globalNews.headline + formatOrderShift(globalNews.effect.orderShift) : 'No global news active right now.'}</p>
    </div>`;

  if (role === 'facilitator') {
    // The Facilitator set all 4 independently, so their box summarizes
    // every role's current pick at a glance - including each role's
    // combined total, so the Facilitator can see how the Global effect
    // they picked interacts with each role's own Local pick, across all
    // 4 roles at once, not just one at a time.
    const summaryRows = CHAIN.map(r => {
      const news = getActiveLocalNewsFor(r);
      const localShift = news ? (news.effect.orderShift || 0) : 0;
      const combined = formatCombinedShift(globalShift, localShift);
      return `<div class="news-box-local-row"><b>${ROLE_ICON[r]} ${ROLE_LABELS[r]}:</b> ${news ? news.headline : '<span class="hint">None</span>'}${combined}</div>`;
    }).join('');
    return `
    <div class="news-boxes">
      ${globalBox}
      <div class="news-box news-box-local">
        <b>📍 Local News (per role)</b>
        ${summaryRows}
      </div>
    </div>`;
  }

  const localNews = getActiveLocalNewsFor(role);
  const localShift = localNews ? (localNews.effect.orderShift || 0) : 0;
  return `
  <div class="news-boxes">
    ${globalBox}
    <div class="news-box news-box-local">
      <b>📍 Local News</b>
      <p>${localNews
        ? localNews.headline + formatOrderShift(localNews.effect.orderShift)
        : 'No local news affecting your role right now.'}</p>
      ${formatCombinedShift(globalShift, localShift)}
    </div>
  </div>`;
}

function renderRolePanel(game, view) {
  const o = view.own;
  const lastFew = o.history.slice(-6);
  const isMulti = state.mode === 'multiplayer';
  const gated = isMulti && !roleUnlockedFor(state.localRole);
  const waitingOnRole = gated ? waitingOnRoleFor(state.localRole) : null;
  const stockWarning = computeStockWarning(o);
  const backlogWarning = computeBacklogWarning(o);
  // This week's order from the buyer, once the buyer has submitted (see the
  // INCOMING ORDER REVEAL notes above) - not last week's number.
  const incomingNow = getRevealedIncomingFor(state.localRole);
  const buyerLabel = 'the ' + ROLE_LABELS[BUYER_OF[state.localRole]];
  const capNow = game.orderCapFor(state.localRole, game.week);
  const capHintHtml = capNow != null ? `<div class="hint iv-cap-hint" id="capHint">🚧 Ceiling set by the Facilitator: at most <b>${capNow}</b> units. Anything higher is cut down to ${capNow}.</div>` : '';
  return `
  <div class="panel two-col">
    <div class="card">
      <h3>${ROLE_ICON[state.localRole]} ${ROLE_LABELS[state.localRole]}: Week ${view.week}</h3>
      <p class="hint">You only see your own numbers and what ${view.upstreamLabel === 'Factory' ? 'the factory' : 'your upstream neighbor'} ships you, not the rest of the chain. That's deliberate.</p>
      ${renderNewsBoxes(state.localRole)}
      ${renderInterventionNotices(state.localRole, game)}
      ${backlogWarning ? `<div class="warning-banner warning-banner-red">${backlogWarning}</div>` : ''}
      ${stockWarning ? `<div class="warning-banner warning-banner-amber">${stockWarning}</div>` : ''}
      <table class="mini-table">
        <thead><tr><th>Current stock</th><th>Current backlog</th><th>Order received this week</th></tr></thead>
        <tbody><tr><td>${o.stock}</td><td class="${o.backlog>0?'neg':''}">${o.backlog}</td><td class="incoming-order">${incomingNow != null
          ? `<b>${incomingNow}</b><span class="incoming-from">from ${buyerLabel}</span>`
          : `--<span class="incoming-from">waiting for ${buyerLabel}'s order</span>`}</td></tr></tbody>
      </table>
      <div class="card-foot">Holding cost: ${fmtRate(game.costRatesFor(state.localRole).holding)}/unit/week · Stockout cost: ${fmtRate(game.costRatesFor(state.localRole).stockout)}/unit/week</div>
    </div>
    <div class="card">
      <h3>Place Your Order</h3>
      ${gated ? `<div class="hint">⏳ Waiting for the ${ROLE_LABELS[waitingOnRole]} to submit before you can order. Submission order this week: Facilitator → Retailer → Wholesaler → Distributor → Manufacturer.</div>`
      : view.isFixedOrderWeek
        ? `<div class="hint">Weeks 1-2 are fixed at <b>4 units</b> per the exercise rules, no decision needed yet.</div>
           <button class="btn-primary btn-block" id="submitOrderBtn" ${state.waitingForOthers?'disabled':''}>${state.waitingForOthers?'Waiting…':'Confirm (4 units) →'}</button>`
        : `<label class="slider-label">Order quantity to ${view.upstreamLabel}</label>
           <input type="number" min="0" id="orderInput" class="full-input" value="${state.draftOrder}" placeholder="e.g. 4" />
           ${capHintHtml}
           <button class="btn-primary btn-block" style="margin-top:14px;" id="submitOrderBtn" ${state.waitingForOthers?'disabled':''}>${state.waitingForOthers?'Waiting…':'Submit Order →'}</button>
           ${renderAiChatbox()}`}
    </div>
  </div>
  <div class="panel" style="margin-top:18px;">
    <div class="card">
      <h3>Your History</h3>
      <table class="mini-table">
        <thead><tr><th>Week</th><th>Stock</th><th>Backlog</th><th>Order In</th><th>Order Placed</th><th>Weekly Cost</th><th>Running Total</th></tr></thead>
        <tbody>${lastFew.map(h => `<tr><td>${h.week}</td><td>${h.stock}</td><td class="${h.backlog>0?'neg':''}">${h.backlog}</td><td>${h.incomingOrder}</td><td>${h.orderPlaced}</td><td>${fmtDollar(h.weeklyCost)}</td><td>${fmtDollar(h.totalCost)}</td></tr>`).join('') || '<tr><td colspan="7" class="hint">No weeks completed yet.</td></tr>'}</tbody>
      </table>
    </div>
  </div>`;
}

function renderFacilitatorNewsPicker() {
  const globalOptions = GLOBAL_NEWS;
  const activeGlobalId = getActiveGlobalNewsId();
  const localByRole = getLocalNewsByRoleMap();
  return `
  <div class="news-picker">
    <h4>📰 News <span class="opt-tag">choose what applies to this session</span></h4>
    <p class="hint news-explainer">Each news item adds or subtracts a fixed number of units on the orders placed that week (never below 0). <b>Global</b> news applies to everyone, including consumer demand, and also shifts holding and stockout costs. <b>Local</b> news applies only to the one role it is picked for, on top of any Global news. Weeks 1-2 are never affected.</p>
    <div class="field">
      <label>🌍 Global News <span class="opt-tag">${globalOptions.length} options, affects everyone</span></label>
      <select id="globalNewsSelect" class="news-select">
        <option value="">None</option>
        ${globalOptions.map(n => `<option value="${n.id}" ${n.id === activeGlobalId ? 'selected' : ''}>${n.headline}</option>`).join('')}
      </select>
    </div>
    <div class="field">
      <label>📍 Local News <span class="opt-tag">a separate pick for each role</span></label>
      <div class="local-news-role-grid">
        ${CHAIN.map(role => {
          const options = LOCAL_NEWS.filter(n => n.targetRole === role);
          const activeId = localByRole[role];
          return `
          <div class="local-news-role-picker">
            <label>${ROLE_ICON[role]} ${ROLE_LABELS[role]} <span class="opt-tag">${options.length} options</span></label>
            <select class="news-select local-news-role-select" data-role="${role}">
              <option value="">None</option>
              ${options.map(n => `<option value="${n.id}" ${n.id === activeId ? 'selected' : ''}>${n.headline}</option>`).join('')}
            </select>
          </div>`;
        }).join('')}
      </div>
    </div>
  </div>`;
}

function renderFacilitatorPanel(game, view) {
  const following = state.facilitatorFollowing; // { teamIndex, role } or null
  const decisionTimeLabel = state.mode === 'multiplayer'
    ? (state.lobby.timerSeconds > 0 ? formatMmSs(state.lobby.timerSeconds) : 'Manual pacing')
    : (state.soloTimerSeconds > 0 ? formatMmSs(state.soloTimerSeconds) : 'Manual pacing');
  const configuredStartingPrice = state.mode === 'multiplayer' ? state.lobby.startingPrice : state.soloStartingPrice;
  const startingPrice = (configuredStartingPrice != null && configuredStartingPrice !== 0)
    ? '$' + Number(configuredStartingPrice).toFixed(2)
    : (marketData.series && marketData.series.length) ? '$' + marketData.series[0].close.toFixed(2) : 'n/a';
  const startingDemand = FIXED_ORDER_QTY;

  return `
  <div class="panel two-col">
    <div class="card">
      <h3>🧑‍🍺 Facilitator: Week ${view.week}</h3>
      <p class="hint">You drive weekly demand for the room. ${state.mode === 'multiplayer' ? 'The 4 chain roles wait for you to submit before they can order.' : ''}</p>
      <div class="baseline-boxes">
        ${SHOW_DECISION_TIMER ? `<div class="baseline-box"><span class="baseline-label">Decision Time</span><span class="baseline-val">${decisionTimeLabel}</span></div>` : ''}
        ${SHOW_STARTING_PRICE ? `<div class="baseline-box"><span class="baseline-label">Starting Price</span><span class="baseline-val">${startingPrice}</span></div>` : ''}
        <div class="baseline-box"><span class="baseline-label">Starting Demand</span><span class="baseline-val">${startingDemand} units</span></div>
      </div>
      ${renderFacilitatorNewsPicker()}
      ${renderNewsBoxes('facilitator')}
      ${view.isFixedOrderWeek
        ? `<div class="hint">Weeks 1-2 use a fixed demand of ${FIXED_ORDER_QTY} (steady-state, before the exercise begins).</div>
           <button class="btn-primary btn-block" id="submitDemandBtn" ${state.waitingForOthers?'disabled':''}>${state.waitingForOthers?'Waiting…':'Confirm (' + FIXED_ORDER_QTY + ' units) →'}</button>`
        : `<label class="slider-label">This week's consumer demand</label>
           <div class="entry-bar">
             <input type="number" min="0" id="demandInput" class="entry-bar-input" value="${state.draftDemand}" placeholder="Type a number, or use the suggestion →" />
             <button class="entry-bar-btn" id="randomDemandBtn" type="button" title="Fill in a scenario-informed suggested demand">💡 Suggested</button>
           </div>
           <button class="btn-primary btn-block" style="margin-top:14px;" id="submitDemandBtn" ${state.waitingForOthers?'disabled':''}>${state.waitingForOthers?'Waiting…':'Submit Demand →'}</button>
           ${renderAiChatbox()}`}
    </div>
    <div class="card">
      <h3>Current Role status</h3>
      <p class="hint">Click any seat below to see that role's situation: their stock, backlog, cost, and week-by-week history.${SHOW_FACILITATOR_LIVE_SCREEN ? ` In multiplayer you'll also see a live view of their screen and what they're typing.` : ''} View only, you can never edit or submit for them.</p>
      <div class="team-grid-wrap">
        <table class="team-grid follow-table">
          <thead><tr>${CHAIN.map(r => `<th>${ROLE_ICON[r]} ${ROLE_LABELS[r]}</th>`).join('')}</tr></thead>
          <tbody>
            ${(state.mode === 'solo' ? [state.game] : state.teams).map((g, ti) => `
              <tr>
                ${CHAIN.map(r => {
                  const isFollowing = following && following.teamIndex === ti && following.role === r;
                  const a = g.roleAssignments[r];
                  return `<td><button class="seat-cell followable-row ${isFollowing ? 'following' : ''}" data-follow-team="${ti}" data-follow-role="${r}">
                    <span class="follow-cell-name">${isFollowing ? '👁 ' : ''}${a.name}${a.isBot ? ' <span class="badge-tiny">AI</span>' : ''}</span>
                    <span class="follow-cell-cost">${fmtDollar(g.roles[r].totalCost)}</span>
                    ${state.mode === 'multiplayer' && ti === 0 ? `<span class="follow-cell-order">${describeSubmittedOrder(getSubmittedOrderFor(r), g.roles[r].history.length ? g.roles[r].history[g.roles[r].history.length - 1].orderPlaced : null)}</span>` : ''}
                  </button></td>`;
                }).join('')}
              </tr>`).join('')}
          </tbody>
        </table>
      </div>
      ${following ? renderFacilitatorFollowDetail((state.mode === 'solo' ? state.game : state.teams[following.teamIndex]), following.teamIndex, following.role) : ''}
      ${SHOW_AI_ORDERING_REVIEW ? renderMistakePanel(state.mode === 'solo' ? state.game : (state.teams ? state.teams[0] : null)) : ''}
    </div>
  </div>
  ${renderInterventionsPanel()}`;
}

// Detailed, read-only week-by-week view of whichever (team, role) the
// Facilitator has clicked to follow: the same history a player sees for
// their own role, just with no controls at all: no input, no edit, purely
// observational, and it can point at any of the 5 teams, not just one.
function renderFacilitatorFollowDetail(game, teamIndex, role) {
  const r = game.roles[role];
  const lastFew = r.history.slice(-6);
  const liveDraft = state.mode === 'multiplayer' ? state.liveDrafts[teamIndex + ':' + role] : null;
  const cursorPos = state.mode === 'multiplayer' ? state.liveCursors[teamIndex + ':' + role] : null;
  const lastClick = state.mode === 'multiplayer' ? state.lastClicks[teamIndex + ':' + role] : null;
  const clickAgeSec = lastClick ? Math.round((Date.now() - lastClick.ts) / 1000) : null;
  const rosterRoles = CHAIN.concat(['facilitator']);

  // Reconstruct what THIS role is actually looking at right now, using the
  // same helpers their own screen uses - so the mock-up reflects their real
  // state (which news they've been given, whether their turn has come up,
  // what their button currently says) rather than generic filler.
  const miniGlobalNews = getActiveGlobalNews();
  const miniLocalNews = getActiveLocalNewsFor(role);
  const miniIsFixedWeek = game.isFixedOrderWeek(game.week);
  const miniWaitingOn = (() => {
    const idx = SUBMISSION_ORDER.indexOf(role);
    for (let i = 0; i < idx; i++) {
      if (!roleHasSubmitted(SUBMISSION_ORDER[i])) return SUBMISSION_ORDER[i];
    }
    return null;
  })();
  const miniUpstream = ROLE_LABELS[UPSTREAM_OF[role]] || 'Factory';

  return `
  <div class="follow-detail">
    <h4>👁 Following: ${ROLE_ICON[role]} ${ROLE_LABELS[role]} <button class="btn-link" id="unfollowBtn">stop following</button></h4>
    ${SHOW_FACILITATOR_LIVE_SCREEN && state.mode === 'multiplayer' ? `<div class="hint">Currently typing: ${liveDraft != null && liveDraft !== '' ? `<b>${liveDraft}</b>` : '(not typing yet)'}</div>` : ''}
    ${SHOW_FACILITATOR_LIVE_SCREEN && state.mode === 'multiplayer' ? `
    <div class="live-activity-box">
      <div class="live-activity-label">👁 Live view <span class="opt-tag">a scaled mock-up of their screen, not a real view</span></div>
      <div class="live-activity-screen">
        <div class="mini-hud">
          <div class="mini-brandwrap">
            <div class="mini-brand">🍺 The Beer Game</div>
            <div class="mini-brandsub">${ROLE_LABELS[role]}${state.lobby && state.lobby.code ? ' · Room ' + state.lobby.code : ''}</div>
          </div>
          <div class="mini-stats">
            <div class="mini-stat"><span>WEEK</span><b>${game.week}<i>/${game.totalWeeks}</i></b></div>
            <div class="mini-stat"><span>STOCK</span><b>${r.stock}</b></div>
            <div class="mini-stat"><span>BACKLOG</span><b>${r.backlog}</b></div>
            <div class="mini-stat"><span>TOTAL COST</span><b>${fmtDollar(r.totalCost)}</b></div>
          </div>
          <div class="mini-gear">⚙️</div>
        </div>
        <div class="mini-body">
          <div class="mini-sidebar">
            <div class="mini-sidebar-title">🏆 Players in This Room</div>
            ${rosterRoles.map(rr => {
              const a = game.roleAssignments[rr];
              const isFollowed = rr === role;
              // Labels are written from the FOLLOWED player's point of view,
              // since this mocks up their screen, not the Facilitator's. So
              // only their own seat reads "You"; every other seat shows that
              // occupant's real name (or "AI" for a bot), exactly as it
              // would appear to them.
              const occupant = isFollowed ? 'You' : (a && a.isBot ? 'AI ' + ROLE_LABELS[rr] : (a && a.name ? a.name : 'Open'));
              return `
              <div class="mini-roster-row ${isFollowed ? 'mini-roster-you' : ''}">
                <span class="mini-roster-icon">${ROLE_ICON[rr]}</span>
                <span class="mini-roster-text">
                  <b>${ROLE_LABELS[rr]}</b>
                  <i>${occupant}</i>
                </span>
              </div>`;
            }).join('')}
            <div class="mini-sidebar-note">Costs and stock stay private to each role until the game ends.</div>
          </div>
          <div class="mini-main">
            <div class="mini-maincol">
              <div class="mini-card mini-role-card">
                <div class="mini-card-title">${ROLE_ICON[role]} ${ROLE_LABELS[role]}: Week ${game.week}</div>
                <div class="mini-hintline">You only see your own numbers and what your upstream neighbor ships you, not the rest of the chain.</div>
                <div class="mini-newsrow">
                  <div class="mini-newsbox"><b>🌍 Global News</b><span>${miniGlobalNews ? miniGlobalNews.headline : 'No global news active right now.'}</span></div>
                  <div class="mini-newsbox mini-newsbox-local"><b>📍 Local News</b><span>${miniLocalNews ? miniLocalNews.headline : 'No local news affecting your role right now.'}</span></div>
                </div>
                <table class="mini-screen-table">
                  <thead><tr><th>Current stock</th><th>Current backlog</th><th>Order received</th></tr></thead>
                  <tbody><tr><td>${r.stock}</td><td class="${r.backlog > 0 ? 'neg' : ''}">${r.backlog}</td><td>${r.incomingOrderThisWeek != null ? r.incomingOrderThisWeek : '--'}</td></tr></tbody>
                </table>
                <div class="mini-costfoot">Holding cost: ${fmtDollar(game.holdingCost)}/unit/week · Stockout cost: ${fmtDollar(game.stockoutCost)}/unit/week</div>
              </div>
              <div class="mini-card mini-history-card">
                <div class="mini-card-title">Your History</div>
                <table class="mini-screen-table mini-history-table">
                  <thead><tr><th>Week</th><th>Stock</th><th>Backlog</th><th>Order in</th><th>Placed</th><th>Cost</th></tr></thead>
                  <tbody>${r.history.length
                    ? r.history.slice(-4).map(h => `<tr><td>${h.week}</td><td>${h.stock}</td><td class="${h.backlog > 0 ? 'neg' : ''}">${h.backlog}</td><td>${h.incomingOrder}</td><td>${h.orderPlaced}</td><td>${fmtDollar(h.weeklyCost)}</td></tr>`).join('')
                    : '<tr><td colspan="6" class="mini-empty">No weeks completed yet.</td></tr>'}</tbody>
                </table>
              </div>
            </div>
            <div class="mini-card mini-order-card">
              <div class="mini-card-title">Place Your Order</div>
              ${miniWaitingOn
                ? `<div class="mini-gated">⏳ Waiting for the ${ROLE_LABELS[miniWaitingOn]} to submit before they can order.</div>`
                : miniIsFixedWeek
                  ? `<div class="mini-hintline">Weeks 1-2 are fixed at <b>4 units</b> per the exercise rules, no decision needed yet.</div>
                     <div class="mini-order-btn">Confirm (4 units) →</div>`
                  : `<div class="mini-hintline">Order quantity to ${miniUpstream}</div>
                     <div class="mini-order-input ${liveDraft != null && liveDraft !== '' ? '' : 'is-empty'}">${liveDraft != null && liveDraft !== '' ? liveDraft : 'e.g. 4'}</div>
                     <div class="mini-order-btn">Submit Order →</div>`}
            </div>
          </div>
        </div>
        ${SHOW_LIVE_CURSOR && cursorPos ? `<div class="live-cursor-dot" id="liveCursorDot" data-team-index="${teamIndex}" data-role="${role}" style="left:${cursorPos.xPct}%;top:${cursorPos.yPct}%;"></div>` : ''}
      </div>
      <div class="hint">Last clicked: ${lastClick ? `<b>${lastClick.label}</b> (${clickAgeSec}s ago)` : 'nothing yet'}</div>
    </div>` : ''}
    <table class="mini-table">
      <thead><tr><th>Week</th><th>Stock</th><th>Backlog</th><th>Order In</th><th>Order Placed</th><th>Weekly Cost</th><th>Running Total</th></tr></thead>
      <tbody>${lastFew.map(h => `<tr><td>${h.week}</td><td>${h.stock}</td><td class="${h.backlog>0?'neg':''}">${h.backlog}</td><td>${h.incomingOrder}</td><td>${h.orderPlaced}</td><td>${fmtDollar(h.weeklyCost)}</td><td>${fmtDollar(h.totalCost)}</td></tr>`).join('') || '<tr><td colspan="7" class="hint">No weeks completed yet.</td></tr>'}</tbody>
    </table>
  </div>`;
}

function bindPlayEvents() {
  if (state.localRole && state.localRole !== 'facilitator') {
    const view = getMyRoleState();
    if (view && view.own) maybeAlertBacklog(view.week, view.own.backlog);
  }
  bindCursorTrackingOnce();
  const submitOrderBtn = document.getElementById('submitOrderBtn');
  if (submitOrderBtn) submitOrderBtn.addEventListener('click', () => {
    const view = getMyRoleState();
    const val = view.isFixedOrderWeek ? FIXED_ORDER_QTY : Number(document.getElementById('orderInput').value) || 0;
    submitDecision(val);
  });
  // Chatbox only exists in the DOM for a real, unlocked decision week
  // (matching exactly the condition it's rendered under) - bindAiChatboxEvents
  // itself no-ops safely if the button isn't present, but computing context
  // is only meaningful when there's an actual decision on screen.
  if (document.getElementById('aiSuggestBtn') && state.localRole && state.localRole !== 'facilitator') {
    const chatView = getMyRoleState();
    const chatGame = getMyGame();
    if (chatView && chatView.own && chatGame) {
      bindAiChatboxEvents(state.localRole, 'orderInput', () => ({
        week: chatView.week,
        totalWeeks: chatView.totalWeeks,
        stock: chatView.own.stock,
        backlog: chatView.own.backlog,
        incomingOrder: (getRevealedIncomingFor(state.localRole) != null ? getRevealedIncomingFor(state.localRole) : chatView.own.incomingOrderThisWeek),
        recentOrdersPlaced: chatView.own.history.slice(-6).map(h => h.orderPlaced),
        holdingCost: chatGame.costRatesFor(state.localRole).holding,
        stockoutCost: chatGame.costRatesFor(state.localRole).stockout,
        orderCap: chatGame.orderCapFor(state.localRole, chatGame.week),
        // Reading straight off the engine instance, which is what
        // applyNewsOrderShiftEffect keeps in sync - guaranteed to match
        // whatever will actually be added at submission time, rather than
        // recomputing it separately here and risking the two drifting.
        pendingOrderShift: chatGame.activeOrderShift + (chatGame.activeLocalOrderShiftByRole[state.localRole] || 0),
      }));
    }
  }
  // broadcast this role's in-progress (not-yet-submitted) draft value, throttled,
  // so the team's Facilitator can watch live while everyone is still deciding;
  // read-only on their end; this never changes what actually gets submitted.
  const orderInputEl = document.getElementById('orderInput');
  if (orderInputEl && state.mode === 'multiplayer') {
    orderInputEl.addEventListener('input', () => {
      state.draftOrder = orderInputEl.value;
      broadcastDraftThrottled(orderInputEl.value);
    });
  }
  const submitDemandBtn = document.getElementById('submitDemandBtn');
  if (submitDemandBtn) submitDemandBtn.addEventListener('click', () => {
    const view = getMyRoleState();
    const val = view.isFixedOrderWeek ? FIXED_ORDER_QTY : Math.max(0, Number(document.getElementById('demandInput').value) || 0);
    submitDecision(val);
  });
  const randomDemandBtn = document.getElementById('randomDemandBtn');
  if (randomDemandBtn) randomDemandBtn.addEventListener('click', () => {
    const input = document.getElementById('demandInput');
    const game = getMyGame();
    const week = game ? game.week : 1;
    const suggested = computeSuggestedDemand(week);
    input.value = suggested;
    state.draftDemand = suggested;
    render();
  });
  // Facilitator has no stock/backlog of their own - they set demand, not an
  // order - so their context is the recent demand trend instead. Same
  // widget, different payload shape; the backend prompt adapts based on
  // whether stock/backlog are present.
  if (document.getElementById('aiSuggestBtn') && state.localRole === 'facilitator') {
    const facGame = getMyGame();
    if (facGame) {
      bindAiChatboxEvents('facilitator', 'demandInput', () => ({
        week: facGame.week,
        totalWeeks: facGame.totalWeeks,
        recentDemand: facGame.weekHistory.slice(-6).map(w => w.consumerDemand),
        // Facilitator has no Local News of their own - only Global News
        // affects consumer demand, mandatorily added at submission.
        pendingOrderShift: facGame.activeOrderShift,
      }));
    }
  }
  const globalNewsSelect = document.getElementById('globalNewsSelect');
  if (globalNewsSelect) globalNewsSelect.addEventListener('change', () => setActiveGlobalNews(globalNewsSelect.value || null));
  bindInterventionEvents();
  document.querySelectorAll('.local-news-role-select').forEach(sel => {
    sel.addEventListener('change', () => setActiveLocalNews(sel.dataset.role, sel.value || null));
  });
  document.querySelectorAll('.followable-row').forEach(row => {
    row.addEventListener('click', () => {
      const teamIndex = Number(row.dataset.followTeam);
      const role = row.dataset.followRole;
      const cur = state.facilitatorFollowing;
      const isSame = cur && cur.teamIndex === teamIndex && cur.role === role;
      state.facilitatorFollowing = isSame ? null : { teamIndex, role };
      render();
    });
  });
  const unfollowBtn = document.getElementById('unfollowBtn');
  if (unfollowBtn) unfollowBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    state.facilitatorFollowing = null;
    render();
  });
  const forceBtn = document.getElementById('forceAdvanceBtn');
  if (forceBtn) forceBtn.addEventListener('click', () => resolveSessionWeek(true));
  const restartBtn = document.getElementById('restartBtnHud');
  if (restartBtn) restartBtn.addEventListener('click', () => restartSolo());
}

function submitDecision(value) {
  if (state.mode === 'solo') {
    stopTimer(); // manual submit: cancel whatever was left of this week's timer before it can fire late
    const decisions = {};
    decisions[state.localRole] = value;
    state.game.processWeek(decisions);
    maybeAutoPickNews(state.game.week);
    state.draftOrder = ''; state.draftDemand = ''; state.aiChatStatus = null;
    state.screen = state.game.gameOver ? 'end' : 'play';
    if (!state.game.gameOver && state.soloTimerSeconds > 0) startTimer();
    render();
    return;
  }
  // multiplayer
  if (state.multiplayerRole === 'guest') {
    state.transport.send({ type: 'submit_decision', teamIndex: state.localTeamIndex, role: state.localRole, value });
    if (state.localRole === 'facilitator') state.facilitatorDone = true;
    state.waitingForOthers = true;
    render();
    return;
  }
  // host (whether or not they also occupy a seat)
  if (state.localRole === 'facilitator') {
    state.pendingHostDecisions.facilitator = value;
    state.facilitatorDone = true;
    state.transport.send({ type: 'facilitator_status', done: true });
    state.waitingForOthers = true;
    broadcastProgress();
    scheduleBotActivityForWeek(); // Retailer's turn may have just opened
    render();
    maybeResolveSessionWeek();
  } else if (state.localTeamIndex != null) {
    state.pendingHostDecisions[state.localTeamIndex + ':' + state.localRole] = value;
    state.waitingForOthers = true;
    broadcastProgress();
    render();
    maybeResolveSessionWeek();
  }
}

