function drawEndBarChart() {
  const canvas = document.getElementById('endBarChart');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  if (!ctx) return; // defensive: canvas 2D context unavailable in this environment
  const W = canvas.width, H = canvas.height;
  ctx.clearRect(0, 0, W, H);
  const game = getMyGame();
  const results = game.finalResults;
  const baseline = game.baseline;
  const maxCost = Math.max(...results.map(r => r.totalCost), ...CHAIN.map(r => baseline.perRole[r]), 1);
  const padding = 50, chartH = H - padding - 30;
  const barW = (W - padding * 1.5) / results.length - 20;
  results.forEach((r, i) => {
    const barH = (r.totalCost / maxCost) * chartH;
    const x = padding + i * ((W - padding * 1.5) / results.length) + 10;
    const y = H - 30 - barH;
    ctx.fillStyle = ROLE_BAR_COLOR[r.role] || '#E0A94A';
    ctx.fillRect(x, y, barW, barH);
    ctx.fillStyle = '#F2E8D5';
    ctx.font = 'bold 13px Calibri, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(fmtDollar(r.totalCost), x + barW / 2, y - 8);
    // baseline marker: dashed line at that role's baseline height
    const baseH = (baseline.perRole[r.role] / maxCost) * chartH;
    const baseY = H - 30 - baseH;
    ctx.save();
    ctx.setLineDash([4, 3]);
    ctx.strokeStyle = '#A8987B';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(x - 4, baseY); ctx.lineTo(x + barW + 4, baseY); ctx.stroke();
    ctx.restore();
    ctx.font = '12px Calibri, sans-serif';
    ctx.fillStyle = '#F2E8D5';
    ctx.fillText(ROLE_LABELS[r.role].replace(' (Facilitator)', ''), x + barW / 2, H - 12);
  });
  ctx.strokeStyle = 'rgba(242,232,213,0.3)';
  ctx.beginPath(); ctx.moveTo(padding - 10, H - 30); ctx.lineTo(W - 10, H - 30); ctx.stroke();
}

function bindEndEvents() {
  const currentGame = getMyGame();
  if (currentGame && state.lastCelebratedGame !== currentGame) {
    state.lastCelebratedGame = currentGame;
    playCelebrationSound();
  }
  document.getElementById('restartEndBtn').addEventListener('click', () => {
    if (state.mode === 'solo') { restartSolo(); return; }
    stopTimer();
    if (state.transport) state.transport.close();
    Object.assign(state, {
      screen: 'modeSelect', mode: null, localRole: null, localTeamIndex: null, multiplayerRole: null, transport: null,
      lobby: null, teams: null, game: null, pendingHostDecisions: {}, facilitatorDone: false, waitingForOthers: false, isAdminHost: false,
      facilitatorFollowing: null, liveDrafts: {}, liveCursors: {}, lastClicks: {},
    });
    render();
  });
  const menuBtn = document.getElementById('menuEndBtn');
  if (menuBtn) menuBtn.addEventListener('click', () => {
    stopTimer();
    Object.assign(state, { screen: 'modeSelect', mode: null, localRole: null, game: null, facilitatorFollowing: null, liveDrafts: {}, liveCursors: {}, lastClicks: {} });
    render();
  });
}

